CREATE DATABASE IF NOT EXISTS neta_sgi CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE neta_sgi;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS payments; DROP TABLE IF EXISTS reservations; DROP TABLE IF EXISTS packages; DROP TABLE IF EXISTS clients; DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('Administrador','Agente de Ventas','Cliente') NOT NULL DEFAULT 'Agente de Ventas',status TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE clients (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(160) NULL,phone VARCHAR(40) NULL,country VARCHAR(80) NULL,preferences VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_client_email(email)) ENGINE=InnoDB;
CREATE TABLE packages (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,destination VARCHAR(160) NOT NULL,category VARCHAR(80) NOT NULL,duration_days INT NOT NULL DEFAULT 1,price DECIMAL(12,2) NOT NULL,currency ENUM('BOB','USD','EUR') NOT NULL DEFAULT 'BOB',stock INT NOT NULL DEFAULT 0,description VARCHAR(255) NULL,status ENUM('Activo','Inactivo') NOT NULL DEFAULT 'Activo',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE reservations (id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(32) NOT NULL UNIQUE,client_id INT NOT NULL,package_id INT NOT NULL,travel_date DATE NOT NULL,passengers INT NOT NULL DEFAULT 1,total_amount DECIMAL(12,2) NOT NULL,status ENUM('Pendiente','Confirmada','Cancelada','Completada') NOT NULL DEFAULT 'Pendiente',notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_res_client FOREIGN KEY(client_id) REFERENCES clients(id),CONSTRAINT fk_res_package FOREIGN KEY(package_id) REFERENCES packages(id)) ENGINE=InnoDB;
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY,reservation_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,payment_date DATE NOT NULL,method ENUM('Transferencia','Efectivo','Tarjeta','QR','Otro') NOT NULL DEFAULT 'Transferencia',reference VARCHAR(100) NULL,notes VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_payment_res FOREIGN KEY(reservation_id) REFERENCES reservations(id)) ENGINE=InnoDB;
